}

.file-detail-card:hover {
  border-color: var(--accent);
}

.file-detail-main {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 1;
}

.file-detail-icon {
  font-size: 1.25rem;
  flex-shrink: 0;
}

.file-detail-meta {
  min-width: 0;
  flex: 1;
}

.file-detail-name {
  color: var(--text-main);
  font-size: 0.85rem;
