350:         cleanFilename += c;
351:       }
352:     }
353:     filename = cleanFilename;
354: 
355:     if (!SD.exists("/uploads")) {
356:       SD.mkdir("/uploads");
357:     }
358:     currentUploadTarget = "/uploads/" + filename;
359: 
360:     // Purge any stale existing file to ensure clean cluster allocation
361:     if (SD.exists(currentUploadTarget)) {
362:       SD.remove(currentUploadTarget);
363:     }
364: 
365:     uploadFile = SD.open(currentUploadTarget, FILE_WRITE);
366:     if (!uploadFile) {
367:       uploadWriteError = true;
368:       Serial.printf("[UPLOAD ERROR] Failed to create destination file: %s\r\n",
369:                     currentUploadTarget.c_str());
370:     } else {
371:       Serial.printf("[UPLOAD START] Destination: %s\r\n", currentUploadTarget.c_str());
372:     }
373:   } else if (upload.status == UPLOAD_FILE_WRITE) {
374:     if (uploadFile && !uploadWriteError && upload.currentSize > 0) {
375:       size_t bytesLeft = upload.currentSize;
376:       size_t srcOffset = 0;
377: 
378:       while (bytesLeft > 0 && !uploadWriteError) {
379:         size_t spaceInBuffer = UPLOAD_SECTOR_BUFFER_SIZE - uploadWriteBufferIndex;
380:         size_t toCopy = (bytesLeft < spaceInBuffer) ? bytesLeft : spaceInBuffer;
