param(
    [string]$JsonlPath = "doc/prompts/17. ESP32 SD Card Sector Write Failure Debugging/transcript_full.jsonl",
    [string]$OutputPath = "doc/prompts/17. ESP32 SD Card Sector Write Failure Debugging/conversation.md"
)

$ErrorActionPreference = "Stop"

$lines = Get-Content -Path $JsonlPath -Encoding UTF8
$steps = [System.Collections.Generic.List[psobject]]::new()

foreach ($line in $lines) {
    if ([string]::IsNullOrWhiteSpace($line)) { continue }
    try {
        $obj = $line | ConvertFrom-Json
        $steps.Add($obj)
    } catch {
        # skip malformed line
    }
}

$sb = [System.Text.StringBuilder]::new()

[void]$sb.AppendLine("# Conversation: ESP32 SD Card Sector Write Failure Debugging")
[void]$sb.AppendLine("")
[void]$sb.AppendLine("- **Conversation ID**: ``fee82fb6-4b78-4c04-9dfd-085b630aceb0``")
[void]$sb.AppendLine("- **Session Folder**: ``doc/prompts/17. ESP32 SD Card Sector Write Failure Debugging/``")
[void]$sb.AppendLine("- **Timestamp**: ``2026-11-14T13:58:00+06:00``")
[void]$sb.AppendLine("- **Model**: ``Gemini 3.8 Flash``")
[void]$sb.AppendLine("")
[void]$sb.AppendLine("---")
[void]$sb.AppendLine("")
[void]$sb.AppendLine("## Table of Contents")
[void]$sb.AppendLine("- [Step-by-Step Trajectory](#step-by-step-trajectory)")

for ($i = 0; $i -lt $steps.Count; $i++) {
    $s = $steps[$i]
    $stepIdx = if ($null -ne $s.step_index) { $s.step_index } else { $i }
    $src = if ($s.source) { $s.source } else { "UNKNOWN" }
    $t = if ($s.type) { $s.type } else { "STEP" }
    $anchor = "step-$stepIdx-$src-$t".ToLower() -replace '[^a-z0-9-]', '-' -replace '-+', '-'
    [void]$sb.AppendLine("  - [Step $stepIdx`: $src / $t](#$anchor)")
}

[void]$sb.AppendLine("")
[void]$sb.AppendLine("---")
[void]$sb.AppendLine("")
[void]$sb.AppendLine("## Step-by-Step Trajectory")
[void]$sb.AppendLine("")

for ($i = 0; $i -lt $steps.Count; $i++) {
    $s = $steps[$i]
    $stepIdx = if ($null -ne $s.step_index) { $s.step_index } else { $i }
    $src = if ($s.source) { $s.source } else { "UNKNOWN" }
    $t = if ($s.type) { $s.type } else { "STEP" }
    $status = if ($s.status) { $s.status } else { "DONE" }
    $created = if ($s.created_at) { $s.created_at } else { "" }

    [void]$sb.AppendLine("### Step $stepIdx`: $src / $t")
    [void]$sb.AppendLine("- **Status**: ``$status``")
    if ($created) {
        [void]$sb.AppendLine("- **Timestamp**: ``$created``")
    }
    [void]$sb.AppendLine("")

    # Thinking
    if ($s.thinking) {
        [void]$sb.AppendLine("#### Thinking")
        [void]$sb.AppendLine('```text')
        [void]$sb.AppendLine($s.thinking.Trim())
        [void]$sb.AppendLine('```')
        [void]$sb.AppendLine("")
    }

    # Tool Calls
    if ($s.tool_calls -and $s.tool_calls.Count -gt 0) {
        [void]$sb.AppendLine("#### Tool Calls")
        foreach ($tc in $s.tool_calls) {
            $fn = $tc.name
            $argsJson = $tc.args | ConvertTo-Json -Depth 10 -Compress
            [void]$sb.AppendLine("- **Function**: ``$fn``")
            [void]$sb.AppendLine("  - **Arguments**:")
            [void]$sb.AppendLine('    ```json')
            [void]$sb.AppendLine("    $argsJson")
            [void]$sb.AppendLine('    ```')
        }
        [void]$sb.AppendLine("")
    }

    # Content
    if ($s.content) {
        [void]$sb.AppendLine("#### Content")
        if ($s.type -eq "USER_INPUT") {
            [void]$sb.AppendLine($s.content.Trim())
        } elseif ($s.type -eq "GENERIC" -or $s.type -eq "SYSTEM_MESSAGE") {
            [void]$sb.AppendLine('```text')
            [void]$sb.AppendLine($s.content.Trim())
            [void]$sb.AppendLine('```')
        } else {
            [void]$sb.AppendLine($s.content.Trim())
        }
        [void]$sb.AppendLine("")
    }

