bool sdWriteSectors(uint8_t pdrv, const char *buffer, unsigned long long sector,
                    int count) {
  // Use sequential single-sector (CMD24) writes to ensure universal compatibility
  // across all SD SPI breakout boards and virtual simulator environments (Wokwi).
  for (int i = 0; i < count; i++) {
    if (!sdWriteSector(pdrv, buffer + (i * 512), sector + i)) {
      return false;
    }
  }
  return true;
}

