394:     return 0;
395:   }
396: 
397:   while (retry) {
398:     //use select to make sure the socket is ready for writing
399:     fd_set set;
400:     struct timeval tv;
401:     FD_ZERO(&set);                       // empties the set
402:     FD_SET(socketFileDescriptor, &set);  // adds FD to the set
403:     tv.tv_sec = 0;
404:     tv.tv_usec = WIFI_CLIENT_SELECT_TIMEOUT_US;
405:     retry--;
406: 
