408:       if (fd() >= 0) {
409:         struct timeval timeout_tv;
410:         timeout_tv.tv_sec = _timeout / 1000;
411:         timeout_tv.tv_usec = (_timeout % 1000) * 1000;
412:         if (setSocketOption(SO_SNDTIMEO, (char *)&timeout_tv, sizeof(struct timeval)) >= 0) {
413:           _lastWriteTimeout = _timeout;
414:         }
415:       }
416:     }
417: 
418:     if (select(socketFileDescriptor + 1, NULL, &set, NULL, &tv) < 0) {
419:       return 0;
420:     }
421: 
422:     if (FD_ISSET(socketFileDescriptor, &set)) {
423:       res = send(socketFileDescriptor, (void *)buf, bytesRemaining, MSG_DONTWAIT);
424:       if (res > 0) {
425:         totalBytesSent += res;
426:         if (totalBytesSent >= size) {
427:           //completed successfully
428:           retry = 0;
429:         } else {
430:           buf += res;
431:           bytesRemaining -= res;
432:           retry = WIFI_CLIENT_MAX_WRITE_RETRY;
433:         }
434:       } else if (res < 0) {
435:         log_e("fail on fd %d, errno: %d, \"%s\"", fd(), errno, strerror(errno));
